import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { CheckCircle } from 'lucide-react';
import { tableAPI, bookingAPI } from '../api';
import { useAuth } from '../context/AuthContext';
import toast from 'react-hot-toast';

export default function Booking() {
  const { isAuth } = useAuth();
  const navigate = useNavigate();
  const [tables, setTables] = useState([]);
  const [form, setForm] = useState({ table_id:'', booking_date:'', start_time:'', end_time:'', number_of_guests:1, special_requests:'' });
  const [loading, setLoading] = useState(false);
  const [success, setSuccess] = useState(false);

  useEffect(() => {
    tableAPI.list().then(r => setTables(r.data.filter(t => t.status === 'available'))).catch(() => {});
  }, []);

  const handle = e => setForm(f => ({ ...f, [e.target.name]: e.target.value }));
  const today = new Date().toISOString().split('T')[0];

  const submit = async e => {
    e.preventDefault();
    if (!isAuth) { toast.error('Please login to book a table'); navigate('/login'); return; }
    setLoading(true);
    try {
      await bookingAPI.create(form);
      setSuccess(true);
      toast.success('Table booked successfully! 🎉');
    } catch (err) {
      const errs = err.response?.data;
      if (errs) Object.values(errs).flat().forEach(m => toast.error(m));
      else toast.error('Booking failed. Please try again.');
    } finally { setLoading(false); }
  };

  if (success) return (
    <div style={{ minHeight:'70vh', display:'flex', alignItems:'center', justifyContent:'center', padding:24 }}>
      <div style={{ background:'#fff', borderRadius:24, padding:'48px 36px', textAlign:'center', boxShadow:'0 8px 40px rgba(74,44,42,0.15)', maxWidth:420, width:'100%' }}>
        <CheckCircle size={68} color="#4caf50" />
        <h2 style={{ fontFamily:'Playfair Display, serif', fontSize:'1.8rem', margin:'20px 0 12px', color:'#2c1a1a' }}>Booking Confirmed!</h2>
        <p style={{ color:'#8d7b72', fontSize:15, marginBottom:32, lineHeight:1.6 }}>Your table has been reserved. We look forward to seeing you!</p>
        <div style={{ display:'flex', gap:12, justifyContent:'center', flexWrap:'wrap' }}>
          <button className="btn-primary" onClick={() => navigate('/bookings')}>My Bookings</button>
          <button className="btn-outline" onClick={() => { setSuccess(false); setForm({ table_id:'', booking_date:'', start_time:'', end_time:'', number_of_guests:1, special_requests:'' }); }}>New Booking</button>
        </div>
      </div>
    </div>
  );

  return (
    <div>
      <div className="page-hero">
        <h1>Reserve Your Table</h1>
        <p>Book your perfect spot at BrewHaven — indoor, outdoor & private rooms available.</p>
      </div>

      <div className="booking-grid">
        {/* Form */}
        <div className="form-card">
          <h3 style={{ fontFamily:'Playfair Display, serif', fontSize:'1.4rem', marginBottom:24, color:'#2c1a1a' }}>Booking Details</h3>
          <form onSubmit={submit}>
            <div className="form-field">
              <label className="form-label">Select Table *</label>
              <select name="table_id" value={form.table_id} onChange={handle} required className="form-select">
                <option value="">Choose a table...</option>
                {tables.map(t => (
                  <option key={t.id} value={t.id}>
                    Table {t.table_number} — {t.location} (seats {t.capacity}){t.has_window_view ? ' 🪟' : ''}{t.has_power_outlet ? ' 🔌' : ''}
                  </option>
                ))}
              </select>
            </div>
            <div className="form-row">
              <div className="form-field">
                <label className="form-label">Date *</label>
                <input type="date" name="booking_date" value={form.booking_date} onChange={handle} min={today} required className="form-input" />
              </div>
              <div className="form-field">
                <label className="form-label">Guests *</label>
                <input type="number" name="number_of_guests" value={form.number_of_guests} onChange={handle} min={1} max={20} required className="form-input" />
              </div>
            </div>
            <div className="form-row">
              <div className="form-field">
                <label className="form-label">Start Time *</label>
                <input type="time" name="start_time" value={form.start_time} onChange={handle} required className="form-input" />
              </div>
              <div className="form-field">
                <label className="form-label">End Time *</label>
                <input type="time" name="end_time" value={form.end_time} onChange={handle} required className="form-input" />
              </div>
            </div>
            <div className="form-field">
              <label className="form-label">Special Requests</label>
              <textarea name="special_requests" value={form.special_requests} onChange={handle} placeholder="Birthday? Anniversary? High chair needed?" rows={3} className="form-textarea" />
            </div>
            {!isAuth && (
              <div style={{ background:'#fff3e0', borderRadius:10, padding:'12px 16px', fontSize:13, color:'#4a2c2a', marginBottom:16, border:'1px solid #ffe0b2' }}>
                🔒 Please <a href="/login" style={{ color:'#d4762a', fontWeight:700 }}>login</a> to make a booking.
              </div>
            )}
            <button type="submit" disabled={loading} className="submit-btn">
              {loading ? 'Booking...' : '✓ Confirm Booking'}
            </button>
          </form>
        </div>

        {/* Info Panel */}
        <div>
          <div className="form-card" style={{ marginBottom:20 }}>
            <h3 style={{ fontFamily:'Playfair Display, serif', fontSize:'1.2rem', marginBottom:18, color:'#2c1a1a' }}>Table Options</h3>
            {[
              { icon:'🪟', title:'Window Seats', desc:'Enjoy city views with natural light', seats:'2' },
              { icon:'🛋️', title:'Indoor Tables', desc:'Comfortable air-conditioned seating', seats:'2–6' },
              { icon:'🌿', title:'Outdoor Patio', desc:'Open-air seating for fresh air lovers', seats:'2–4' },
              { icon:'🤝', title:'Conference Room', desc:'Perfect for meetings & group sessions', seats:'8' },
            ].map(t => (
              <div key={t.title} style={{ display:'flex', gap:12, marginBottom:16, padding:12, borderRadius:10, background:'#f5efe6', alignItems:'flex-start' }}>
                <span style={{ fontSize:26, flexShrink:0 }}>{t.icon}</span>
                <div>
                  <div style={{ fontWeight:700, fontSize:14, color:'#2c1a1a' }}>{t.title} <span style={{ fontSize:12, color:'#8d7b72', fontWeight:400 }}>({t.seats} seats)</span></div>
                  <div style={{ fontSize:13, color:'#8d7b72', marginTop:2 }}>{t.desc}</div>
                </div>
              </div>
            ))}
          </div>

          <div style={{ background:'#1a0f0f', color:'#f5efe6', borderRadius:18, padding:'22px 24px' }}>
            <h4 style={{ fontFamily:'Playfair Display, serif', fontSize:'1.1rem', marginBottom:16 }}>⏰ Opening Hours</h4>
            <div style={{ display:'flex', justifyContent:'space-between', marginBottom:10, fontSize:14 }}><span style={{ opacity:0.8 }}>Monday – Friday</span><strong>7:00 AM – 10:00 PM</strong></div>
            <div style={{ display:'flex', justifyContent:'space-between', fontSize:14 }}><span style={{ opacity:0.8 }}>Saturday – Sunday</span><strong>8:00 AM – 11:00 PM</strong></div>
          </div>
        </div>
      </div>
    </div>
  );
}
